/*
 * Source-backed static dashboard. All published observations come from
 * data/latest.json and data/history.json generated by the GitHub Actions
 * collector. Never generate a numeric "tomorrow" prediction here.
 */
const cities = ['Chennai', 'Mumbai', 'Delhi', 'Bengaluru', 'Hyderabad'];
const app = document.querySelector('#app');
const cityPicker=document.querySelector('#city-picker');
const cityTrigger=document.querySelector('#city-trigger');
const cityMenu=document.querySelector('#city-menu');
const selectedCity=document.querySelector('#selected-city');
let currentCity='Chennai';
let activeMetal = 'gold24';
let weightMetal = 'gold22';
let customWeight = '8';
let customUnit = 'g';
let rates = null;
let history = null;
let forecast = null;
let funds = null;
let buyMetal = 'gold';
let buyGrams = 8;
let activeForecastMetal = 'gold24';
let loadFailure = null;
let forecastLoadFailure = false;
let navLoadFailure = false;

const INR = new Intl.NumberFormat('en-IN', {style: 'currency', currency: 'INR', maximumFractionDigits: 0});
const USD = new Intl.NumberFormat('en-US', {style: 'currency', currency: 'USD', maximumFractionDigits: 2});
const icon = (name, cls='icon') => '<svg class="' + cls + '" aria-hidden="true"><use href="#i-' + name + '"/></svg>';
const price = n => Number.isFinite(Number(n)) ? INR.format(Number(n)) : 'Unavailable';
const usd = n => Number.isFinite(Number(n)) ? USD.format(Number(n)) : 'Unavailable';
const escapeHTML = v => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function sourceDate(iso) {
  if (!iso || !/^\d{4}-\d\d-\d\d$/.test(iso)) return 'Date unavailable';
  return new Date(iso + 'T12:00:00+05:30').toLocaleDateString('en-IN', {timeZone:'Asia/Kolkata',day:'numeric',month:'short',year:'numeric'});
}
function sourceTime(iso) {
  if (!iso) return 'Time unavailable';
  const dt = new Date(iso);
  if (!Number.isFinite(dt.getTime())) return 'Time unavailable';
  return dt.toLocaleString('en-IN', {timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'numeric',minute:'2-digit',hour12:true})+' IST';
}
function daysOld(dateString) {
  if (!dateString) return Infinity;
  const date = new Date(dateString.slice(0,10)+'T00:00:00Z');
  if (!Number.isFinite(date.getTime())) return Infinity;
  const parts = new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const part = key => parts.find(p=>p.type===key)?.value;
  const utcToday = new Date(part('year')+'-'+part('month')+'-'+part('day')+'T00:00:00Z');
  return Math.max(0, Math.floor((utcToday-date)/86400000));
}
const india = () => rates?.india || null;
const series = () => Array.isArray(history?.india) ? history.india.slice().sort((a,b)=>a.date.localeCompare(b.date)) : [];

function benchmark(metal) {
  const info = {
    gold24: {key:'gold24_inr_10g',label:'24K Gold',unit:'₹ / 10g',icon:'bars'},
    gold22: {key:'gold22_inr_10g',label:'22K Gold',unit:'₹ / 10g',icon:'bars'},
    silver: {key:'silver999_inr_kg',label:'Silver 999',unit:'₹ / kg',icon:'silver'}
  }[metal];
  return {...info, value: india()?.[info.key] ?? null};
}
function previousObservation(key) {
  const d=india()?.date;
  return series().filter(r=>r.date<d && Number.isFinite(r[key])).at(-1);
}
function movement(key, current) {
  const old = previousObservation(key);
  const prev=old?.[key];
  if (!Number.isFinite(current)||!Number.isFinite(prev)||prev===0) return '<span class="muted">No earlier observation</span>';
  const delta=(current-prev)/prev*100;
  const positive=delta>=0;
  return '<span class="change '+(positive?'':'down')+'">'+(positive?'▲ +':'▼ ')+delta.toFixed(2)+'%</span><span class="muted"> vs '+sourceDate(old.date)+'</span>';
}
function availabilityTag() {
  const p=india();
  if (!p) return '<span class="date status-warning">'+icon('calendar')+'Indian rates unavailable</span>';
  const stale=daysOld(p.date)>4;
  return '<span class="date '+(stale?'status-warning':'')+'">'+icon('calendar')+(stale?'Older reference':'IBJA '+escapeHTML(p.session||'last'))+' · '+sourceDate(p.date)+'</span>';
}
function heading(title,sub) {
  return '<section class="hero"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+availabilityTag()+'</section>';
}
function benchmarkCard(which) {
  const b=benchmark(which);
  const ok=Number.isFinite(b.value);
  return '<article class="card"><div class="price-top">'+'<img class="metal metal-photo" src="./assets/'+(b.icon==='silver'?'silver-bar.webp':'gold-bar.webp')+'?v=20261025-theme2" width="52" height="52" alt="" decoding="async">'+
    '<div><strong>'+b.label+'</strong><div class="muted">'+b.unit+'</div></div></div>'+
    '<div class="price">'+(ok?price(b.value):'—')+'</div>'+
    '<div class="price-change">'+(ok?movement(b.key,b.value):'<span class="muted">Awaiting validated quote</span>')+'</div>'+
    (ok?'<div class="per-gram">1 gram · <strong>'+NextRateWeights.formatINR(NextRateWeights.calculate(b.value,which,1).amount)+'</strong></div>':'')+
    '</article>';
}
function note() {
  const p=india();
  let message = p
    ? 'National IBJA benchmark for '+sourceDate(p.date)+' ('+escapeHTML(p.session||'last')+'). Prices exclude GST and making charges. These are not jewellery-shop or city-specific selling prices.'
    : 'IBJA reference rates are currently unavailable. No placeholder or estimated retail prices are shown.';
  if (p && daysOld(p.date)>4) message+=' This observation is older than four days: check the publisher for newer rates.';
  return '<p class="notice">'+message+' <a href="https://www.ibjarates.com/" target="_blank" rel="noopener noreferrer">Source: IBJA ↗</a></p>';
}
function chart() {
  const points=series().filter(r=>Number.isFinite(r.gold24_inr_10g)).slice(-7);
  if (points.length<2) {
    return '<div class="empty-chart">A price-history chart will appear after at least two verified dated observations are available.</div>';
  }
  const nums=points.map(r=>r.gold24_inr_10g);
  let low=Math.min(...nums), high=Math.max(...nums);
  const padding=Math.max((high-low)*.2,high*.002);
  low-=padding;high+=padding;
  const px=i=>45+(i/(points.length-1))*575;
  const py=v=>204-(v-low)/(high-low)*155;
  const coords=nums.map((v,i)=>[px(i),py(v)]);
  const path=coords.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
  const base=coords.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')+
    ' L'+coords.at(-1)[0]+' 213 L'+coords[0][0]+' 213 Z';
  const labels=points.map((r,i)=>'<text x="'+px(i).toFixed(1)+'" y="249" text-anchor="middle">'+
    new Date(r.date+'T12:00:00+05:30').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'})+'</text>').join('');
  const circles=coords.map(([x,y])=>'<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="4" fill="#fff" stroke="#d99a18" stroke-width="3"/>').join('');
  return '<svg class="chart" viewBox="0 0 650 255" role="img" aria-label="Actual dated IBJA 24K gold prices for the last '+points.length+' published observations">'+
    '<defs><linearGradient id="shade" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#e9ad2b" stop-opacity=".24"/><stop offset="1" stop-color="#e9ad2b" stop-opacity="0"/></linearGradient></defs>'+
    [55,105,155,205].map(y=>'<line x1="40" x2="635" y1="'+y+'" y2="'+y+'" stroke="#eef0f3"/>').join('')+
    '<path d="'+base+'" fill="url(#shade)"/><path d="'+path+'" fill="none" stroke="#dda020" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'+
    circles+'<g fill="#8793a4" font-size="13">'+labels+'</g></svg>';
}

/* Proportional India bullion weights using the actual dated IBJA rates. */
function weightPriceSection(){
  const selected=benchmark(weightMetal);
  const published=Number.isFinite(selected.value)&&selected.value>0;
  const weights=NextRateWeights.POPULAR_WEIGHTS[weightMetal];
  const tabs=[['gold24','24K Gold'],['gold22','22K Gold'],['silver','Silver 999']]
    .map(([key,label])=>'<button class="weight-tab'+(weightMetal===key?' active':'')+
      '" type="button" data-weight-metal="'+key+'" aria-pressed="'+(weightMetal===key)+'">'+label+'</button>').join('');
  const options=weights.map(grams=>{
    const converted=published?NextRateWeights.calculate(selected.value,weightMetal,grams):null;
    const isActive=Number(customWeight)*(customUnit==='kg'?1000:1)===grams;
    const extra=grams===8&&weightMetal!=='silver'?'<small>1 sovereign / pavan</small>':'';
    return '<button type="button" class="weight-option'+(isActive?' selected':'')+
      '" data-weight-grams="'+grams+'" aria-label="Calculate '+grams+' grams of '+selected.label+'">'+
      '<span class="weight-name">'+NextRateWeights.gramLabel(grams)+extra+'</span>'+
      '<strong class="weight-price">'+(converted?NextRateWeights.formatINR(converted.amount):'—')+'</strong></button>';
  }).join('');
  let initialValue='—';
  if(published){try{
    initialValue=NextRateWeights.formatINR(NextRateWeights.calculate(
      selected.value,weightMetal,customWeight,customUnit).amount);
  }catch{initialValue='—';}}
  return '<section class="card section weight-panel" data-selected-metal="'+weightMetal+
    '" aria-labelledby="weights-heading">'+
    '<div class="weight-section-header"><div><h2 id="weights-heading">By Weight</h2>'+
    '<p class="muted">1 g · 8 g (Pavan) · 10 g</p></div>'+
    '<span class="weight-date">'+(india()?'IBJA · '+sourceDate(india().date):'Rates unavailable')+'</span></div>'+
    '<div class="weight-tabs" role="group" aria-label="Select metal for weight prices">'+tabs+'</div>'+
    '<p class="weight-rate-line">'+selected.label+' · '+selected.unit+' benchmark: <strong>'+
    (published?price(selected.value):'Unavailable')+'</strong></p>'+
    '<div class="weight-grid" aria-label="Common bullion weights">'+options+'</div>'+
    '<div class="weight-calculator"><div class="weight-calculator-heading"><h3>Custom Weight</h3>'+
    '<p class="muted">Enter grams or kg</p></div>'+
    '<div class="weight-custom-row"><div class="weight-entry">'+
    '<label for="custom-weight">Weight</label>'+
    '<input type="number" id="custom-weight" min="0.01" max="100000" step="any" inputmode="decimal" value="'+escapeHTML(customWeight)+'" placeholder="e.g. 8" aria-describedby="weight-error"></div>'+
    '<div class="weight-unit-entry"><span class="field-label" id="unit-label">Unit</span>'+
    '<div class="unit-toggle" role="group" aria-labelledby="unit-label">'+
    '<button type="button" class="unit-button'+(customUnit==='g'?' active':'')+'" data-unit="g" aria-pressed="'+(customUnit==='g')+'" aria-label="Grams">g</button>'+
    '<button type="button" class="unit-button'+(customUnit==='kg'?' active':'')+'" data-unit="kg" aria-pressed="'+(customUnit==='kg')+'" aria-label="Kilograms">kg</button></div></div>'+
    '<div class="weight-total" role="status" aria-live="polite" aria-atomic="true">'+
    '<span>Metal value</span><strong id="weight-result">'+initialValue+'</strong>'+
    '<small id="weight-result-basis">'+(published?'Based on national IBJA '+selected.unit+' benchmark':'Waiting for a verified rate')+'</small></div></div>'+
    '<p id="weight-error" class="weight-error" aria-live="polite"></p></div>'+
    '<p class="weight-disclaimer">Reference metal value only · Excludes GST, making charges and local dealer premiums. Calculated from the IBJA '+escapeHTML(selected.unit)+' rate, not a retail shop quotation.</p>'+
    '</section>';
}

function updateCustomWeight(){
  const result=document.querySelector('#weight-result');
  const basis=document.querySelector('#weight-result-basis');
  const error=document.querySelector('#weight-error');
  if(!result||!basis||!error)return;
  const b=benchmark(weightMetal);
  document.querySelectorAll('[data-weight-grams]').forEach(card=>
    card.classList.toggle('selected',Number(customWeight)*(customUnit==='kg'?1000:1)===Number(card.dataset.weightGrams))
  );
  if(!Number.isFinite(b.value)||b.value<=0){
    result.textContent='—';
    basis.textContent='No published benchmark available';
    error.textContent='';
    return;
  }
  try{
    const value=NextRateWeights.calculate(b.value,weightMetal,customWeight,customUnit);
    result.textContent=NextRateWeights.formatINR(value.amount);
    basis.textContent='For '+value.grams.toLocaleString('en-IN',{maximumFractionDigits:3})+
      ' g · '+b.label+' · IBJA '+sourceDate(india().date);
    error.textContent='';
  }catch(err){
    result.textContent='—';
    basis.textContent='Enter a valid weight to see its value';
    error.textContent=err.message;
  }
}

function wireWeightCalculator(){
  document.querySelectorAll('[data-weight-metal]').forEach(tab=>
    tab.addEventListener('click',()=>{weightMetal=tab.dataset.weightMetal;render();})
  );
  document.querySelectorAll('[data-weight-grams]').forEach(button=>
    button.addEventListener('click',()=>{
      const grams=Number(button.dataset.weightGrams);
      if(grams>=1000){customWeight=String(grams/1000);customUnit='kg';}
      else{customWeight=String(grams);customUnit='g';}
      const input=document.querySelector('#custom-weight');
      if(input)input.value=customWeight;
      syncUnitButtons();
      updateCustomWeight();
    })
  );
  const input=document.querySelector('#custom-weight');
  if(input)input.addEventListener('input',()=>{customWeight=input.value;updateCustomWeight();});
  document.querySelectorAll('.unit-button').forEach(button=>
    button.addEventListener('click',()=>{
      customUnit=button.dataset.unit;
      syncUnitButtons();
      updateCustomWeight();
    })
  );
}
function syncUnitButtons(){
  document.querySelectorAll('.unit-button').forEach(button=>{
    const active=button.dataset.unit===customUnit;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
  });
}

function spotRow(symbol,label) {
  const r=rates?.spot?.[symbol];
  if (!r) return '<div class="driver"><span class="driver-label">'+icon('globe')+'<strong>'+label+'</strong></span><span class="muted">Unavailable</span></div>';
  return '<div class="driver"><span class="driver-label">'+icon('globe')+'<strong>'+label+'</strong></span><span><b>'+usd(r.usd_per_troy_ounce)+'</b><small class="subdate">'+sourceTime(r.as_of)+'</small></span></div>';
}

/**
 * Future India benchmark outlook. All figures come from forecast.json,
 * generated server-side from pre-existing published IBJA data.
 * No client-made forecasts or fake probability/confidence scores.
 */
function indiaTodayISO(){
  const pieces=new Intl.DateTimeFormat('en-GB',{
    timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'
  }).formatToParts(new Date());
  const get=key=>pieces.find(p=>p.type===key)?.value;
  return get('year')+'-'+get('month')+'-'+get('day');
}
function forecastDate(value){
  return /^20\d\d-\d\d-\d\d$/.test(value||'') ? sourceDate(value) : 'Date unavailable';
}
function forecastDataIsCurrent(){
  return forecast && forecast.schema_version===1 && forecast.status==='experimental' &&
    forecast.target_date >= indiaTodayISO() && forecast.metals && forecast.metals.gold24 &&
    forecast.metals.gold22 && forecast.metals.silver;
}

function forecastMetalCard(key, title, unit, iconFile){
  const data=forecast?.metals?.[key];
  const valid=data&&['estimate','low','high','baseline'].every(k=>
    typeof data[k]==='number' && Number.isFinite(data[k]) && data[k]>0
  );
  const selected=activeForecastMetal===key;
  if(!valid)return '<div class="forecast-metal"><strong>'+title+'</strong><span>Estimate unavailable</span></div>';
  const direction=['Up','Down','Mostly steady'].includes(data.direction)?data.direction:'Mostly steady';
  const dirClass=direction==='Up'?'is-up':direction==='Down'?'is-down':'is-steady';
  const change=typeof data.expected_change_pct==='number'&&Number.isFinite(data.expected_change_pct)
    ? data.expected_change_pct : (data.estimate/data.baseline-1)*100;
  const percent=(change>0?'+':'')+change.toFixed(2)+'%';
  const diff=data.estimate-data.baseline;
  const delta=(diff>0?'+':'−')+price(Math.abs(diff));
  const quickWeights=(key==='silver'?[1,100]:[1,8]).map(grams=>
    '<span>'+grams+' g <b>'+NextRateWeights.formatINR(NextRateWeights.calculate(data.estimate,key,grams).amount)+'</b></span>'
  ).join('');
  return '<button type="button" class="forecast-metal'+(selected?' selected':'')+
    '" data-forecast-metal="'+key+'" aria-pressed="'+selected+'" aria-label="'+title+
    ' expected '+price(data.estimate)+', '+direction+' '+percent+', tap to view trend">'+
    '<span class="forecast-metal-head"><img class="forecast-metal-img" src="./assets/'+iconFile+
    '?v=20261025-market2" width="38" height="38" alt="" loading="eager">'+
    '<span class="forecast-metal-name"><strong>'+title+'</strong><small>'+unit+'</small></span></span>'+
    '<span class="forecast-metal-quote"><strong>'+price(data.estimate)+'</strong>'+
    '<span class="forecast-direction '+dirClass+'">'+(change>0?'▲ ':change<0?'▼ ':'● ')+
    percent+' <small>'+delta+'</small></span></span>'+
    '<span class="forecast-range"><span>Range</span><strong>'+price(data.low)+' – '+price(data.high)+'</strong></span>'+
    '<span class="forecast-quick-weights">'+quickWeights+'</span></button>';
}
function marketGraph(){
  const data=forecast?.metals?.[activeForecastMetal];
  const field={gold24:'gold24_inr_10g',gold22:'gold22_inr_10g',silver:'silver999_inr_kg'}[activeForecastMetal];
  const title={gold24:'24K Gold',gold22:'22K Gold',silver:'Silver 999'}[activeForecastMetal];
  if(!data||!field)return '<div class="empty-chart">Select a metal to view its trend.</div>';
  const observed=series().filter(r=>
    r.date<=forecast.based_on_date &&
    typeof r[field]==='number' && Number.isFinite(r[field]) && r[field]>0
  ).slice(-7);
  if(observed.length<2)return '<div class="empty-chart">The historical chart will appear after two published IBJA observations.</div>';
  const low=Math.min(...observed.map(r=>r[field]),data.low,data.estimate);
  const high=Math.max(...observed.map(r=>r[field]),data.high,data.estimate);
  const margin=Math.max((high-low)*.12,high*.003);
  const floor=low-margin,ceil=high+margin;
  const y=value=>205-((value-floor)/(ceil-floor))*158;
  const x0=55,xEnd=480,xPred=590;
  const pts=observed.map((r,i)=>({x:x0+(xEnd-x0)*i/(observed.length-1),y:y(r[field]),date:r.date,value:r[field]}));
  const last=pts[pts.length-1];
  const currentLabel=sourceDate(observed[observed.length-1].date);
  const startLabel=sourceDate(observed[0].date);
  const shortDate=iso=>{
    const d=new Date(iso+'T12:00:00+05:30');
    return d.toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'});
  };
  const numLabel=value=>{
    if(value>=100000)return '₹'+(value/100000).toFixed(2)+'L';
    if(value>=1000)return '₹'+(value/1000).toFixed(1)+'K';
    return price(value);
  };
  const color=activeForecastMetal==='silver'?'#7d8d9f':'#c49430';
  const moveClass=data.estimate>=last.value?'#12846b':'#cf5252';
  const line=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');
  const fill=line+' L'+last.x+' 214 L'+x0+' 214 Z';
  const ticks=[0,.25,.5,.75,1].map(f=>{
    const value=floor+(ceil-floor)*f;
    const yy=y(value);
    return '<line x1="55" y1="'+yy.toFixed(1)+'" x2="617" y2="'+yy.toFixed(1)+'" stroke="#ebedf2" stroke-width="1"/>'+
       '<text x="47" y="'+(yy+5).toFixed(1)+'" text-anchor="end" font-size="12" fill="#8a96a6">'+numLabel(value)+'</text>';
  }).join('');
  const candles=pts.map(p=>'<circle cx="'+p.x.toFixed(1)+'" cy="'+p.y.toFixed(1)+'" r="4" fill="#fff" stroke="'+color+'" stroke-width="2.5"/>').join('');
  const rangeTop=y(data.high),rangeBottom=y(data.low);
  const rectY=Math.min(rangeTop,rangeBottom),rectH=Math.abs(rangeBottom-rangeTop);
  const projectedY=y(data.estimate);
  const areaColor=activeForecastMetal==='silver'?'#c7d0d9':'#efcf80';
  return '<div class="market-chart-title"><div><strong>'+title+' Price Trend</strong>'+
    '<span>Actual → '+shortDate(forecast.target_date)+' estimate</span></div>'+
    '<span class="market-chart-metadata">₹ / '+(activeForecastMetal==='silver'?'kg':'10 g')+'</span></div>'+
    '<svg class="market-trend-svg" viewBox="0 0 640 257" role="img" aria-label="'+title+
    ' actual dated IBJA close from '+startLabel+' to '+currentLabel+
    '. Dashed section indicates estimated '+forecastDate(forecast.target_date)+
    ' price '+price(data.estimate)+', scenario range '+price(data.low)+' to '+price(data.high)+'">'+
    '<defs><linearGradient id="market-actual-fill" x1="0" y1="0" x2="0" y2="1">'+
    '<stop offset="0" stop-color="'+areaColor+'" stop-opacity=".30"/>'+
    '<stop offset="1" stop-color="'+areaColor+'" stop-opacity="0"/></linearGradient></defs>'+
    ticks+
    '<path d="'+fill+'" fill="url(#market-actual-fill)" />'+
    '<path d="'+line+'" fill="none" stroke="'+color+'" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/>'+
    candles+
    '<line x1="533" y1="40" x2="533" y2="218" stroke="#bbc3cf" stroke-width="1" stroke-dasharray="3 5"/>'+
    '<rect x="'+(xPred-16)+'" y="'+rectY.toFixed(1)+'" width="32" height="'+Math.max(rectH,2).toFixed(1)+
       '" rx="5" fill="'+areaColor+'" fill-opacity=".45" stroke="#c7ac70" stroke-width="1"/>'+
    '<path d="M'+last.x.toFixed(1)+' '+last.y.toFixed(1)+' L'+xPred+' '+projectedY.toFixed(1)+
    '" fill="none" stroke="'+moveClass+'" stroke-width="3" stroke-dasharray="6 5" stroke-linecap="round"/>'+
    '<circle cx="'+xPred+'" cy="'+projectedY.toFixed(1)+'" r="6" fill="'+moveClass+'" stroke="white" stroke-width="2"/>'+
    '<text x="'+x0+'" y="242" font-size="13" fill="#8492a3">'+shortDate(observed[0].date)+'</text>'+
    '<text x="'+xEnd+'" y="242" text-anchor="middle" font-size="13" fill="#8492a3">'+shortDate(observed.at(-1).date)+'</text>'+
    '<text x="'+xPred+'" y="242" text-anchor="middle" font-size="13" font-weight="700" fill="#aa7416">'+shortDate(forecast.target_date)+'</text>'+
    '</svg>'+
    '<div class="market-legend"><span><i class="market-legend-line"></i>Actual</span>'+
    '<span><i class="market-legend-dash"></i>Estimate</span>'+
    '<span><i class="market-legend-band"></i>Range</span></div>';
}
function marketSnapshot(){
  const xau=rates?.spot?.XAU;
  const xag=rates?.spot?.XAG;
  const fx=rates?.fx;
  const items=[
    ['GOLD / USD',xau?usd(xau.usd_per_troy_ounce):'—',xau?sourceTime(xau.as_of):'Unavailable'],
    ['SILVER / USD',xag?usd(xag.usd_per_troy_ounce):'—',xag?sourceTime(xag.as_of):'Unavailable'],
    ['USD / INR',fx?Number(fx.inr_per_usd).toFixed(3):'—',fx?sourceDate(fx.date):'Unavailable']
  ];
  return '<div class="market-reference"><div class="market-reference-label">'+
    '<strong>MARKET REFERENCES</strong><small>Not yet model inputs</small></div>'+
    items.map(([name,value,date])=>
      '<div class="market-reference-item"><span>'+name+'</span><strong>'+value+
      '</strong><small>'+date+'</small></div>'
    ).join('')+
    '<a class="market-reference-link" href="#markets" aria-label="View all market details">View Markets →</a></div>';
}
function forecastPanel(){
  const valid=forecastDataIsCurrent();
  const date=valid?forecastDate(forecast.target_date):'—';
  const based=valid?sourceDate(forecast.based_on_date):'—';
  let content='<section class="forecast-shell" aria-labelledby="forecast-title">'+
    '<div class="nr-top"><div><span class="nr-kicker">INDIA · NEXT RATE</span>'+
    '<h1 id="forecast-title">Tomorrow</h1></div><span class="forecast-tag">Estimate</span></div>';
  if(!valid){
    const reason=forecast?.status==='unavailable'?
      escapeHTML(forecast.reason||'No forecast'): 'Next forecast not ready';
    return content+'<p class="nr-empty">'+reason+'</p></section>';
  }
  content+='<div class="nr-date">'+date+
    (forecast.target_date===forecast.calendar_tomorrow?'':' · Next open day')+
    '<span>IBJA · '+based+'</span></div>'+
    '<div class="forecast-grid" role="group" aria-label="Choose gold or silver">'+
    forecastMetalCard('gold24','24K Gold','10 g','gold-bar.webp')+
    forecastMetalCard('gold22','22K Gold','10 g','gold-bar.webp')+
    forecastMetalCard('silver','Silver','1 kg','silver-bar.webp')+'</div>'+
    '<div class="nr-chart">'+marketGraph()+'</div>'+
    '<details class="nr-small-details"><summary>How?</summary>'+
    '<p>IBJA '+forecast.observations+' dates · Test model. Range is not a guarantee.</p>'+
    '<p>LBMA, COMEX and MCX are not yet model inputs. Shop prices vary.</p></details></section>';
  return content;
}

function verifiedNav(key){
  const nav=funds?.funds?.[key];
  if(!nav || typeof nav.nav_inr_per_unit!=='number' ||
    !Number.isFinite(nav.nav_inr_per_unit) || nav.nav_inr_per_unit<=0 ||
    !/^\d{4}-\d\d-\d\d$/.test(nav.nav_date||'') || daysOld(nav.nav_date)>10)return null;
  return nav;
}
function buyingRow(name,place,amount,unit,note,href){
  const link=href?'<a class="buy-link" target="_blank" rel="noopener noreferrer" href="'+href+
    '" aria-label="More about '+escapeHTML(name)+'">↗</a>':'';
  return '<div class="buy-row"><div class="buy-kind"><strong>'+escapeHTML(name)+
    '</strong><span>'+escapeHTML(place)+'</span></div>'+
    '<div class="buy-cost"><strong>'+amount+'</strong><small>'+escapeHTML(unit)+'</small></div>'+
    '<div class="buy-note">'+escapeHTML(note)+'</div>'+link+'</div>';
}
